let events = "";
function mark(label, value) { events = events + label; return value; }
export function reset() { events = ""; }
export function trace() { return events; }
export const slots = (a, b, c) => {
  console.log("slots", a === undefined, a === null, b === undefined, b === null, c === undefined, c === null);
  return c;
};
export const defaults = (a = mark("a", "first"), b = mark("b", a), c = mark("c", b)) => {
  events = events + "!";
  console.log("defaults", String(a), String(b), String(c));
  return c;
};
export const empty = () => "empty";
export const ordinary = function (value, second) {
  console.log("receiver", this === undefined, String(value), String(second));
  return value;
};
export const JSONStringify = (value, replacer, space) => JSON.stringify(value, replacer, space);
export const JSONParse = (text, reviver) => JSON.parse(text, reviver);
/** @param {string} value */
export const annotated = (value) => value === undefined;
export const make = (value) => () => { value = value + "!"; return value; };
export function named(first = "default", second = first) { return String(first) + ":" + String(second); }
export const captureDefault = (a = "start", b = () => a) => { a = a + "!"; return b; };
function failDefault() { events = events + "X"; if (events.length > 0) throw new Error("default"); return "unreachable"; }
export const throwsDefault = (a = mark("a", 1), b = failDefault(), c = mark("c", 3)) => b;
